    uy = dy / dist
    fx = thrust_mag * ux
    fy = thrust_mag * uy
    if y < 1.4:
        fy += 100.0
    if x < G1_X + 1.0 and y < 1.1:
        fy += min(30.0, (1.2 - y) * 40.0)
    if 20.5 <= x <= G2_X + 2.0 and y < 1.9:
        fy += 110.0
    if x > 25.0 and y < 3.0:
        fy += 120.0
    if SLIP_LO <= x <= SLIP_HI:
        fx += 35.0
    if WIND_LO <= x <= WIND_HI:
        wind_fy = WIND_AMP * math.sin(WIND_OMEGA * step_idx)
        fy -= wind_fy
    total = math.sqrt(fx * fx + fy * fy)
    cap = thrust_mag * 2.5
    if y < 1.4:
        cap = max(cap, 180.0)
    if 20.5 <= x <= G2_X + 2.0 and y < 1.9:
        cap = max(cap, 250.0)
    if total > cap:
        scale = cap / total
        fx *= scale
        fy *= scale
    sandbox.apply_thrust(fx, fy)

