    step_idx = sandbox.get_step_count() if hasattr(sandbox, "get_step_count") else step_count

    # Strict thermal safety check: cap thrust at 20 N in high-drag zones
    if DRAIN_LO <= x <= DRAIN_HI:
        thrust_mag = min(20.0, remaining * 0.35)
    else:
        # Normal thrust calculation with heat-aware adjustments
        if heat >= overheat_limit * HEAT_SAFE_FRAC:
            thrust_mag = min(LOW_THRUST, remaining * 0.25)
        else:
            thrust_mag = min(MAX_THRUST, remaining * 0.35)

    # Check for gate proximity and boost thrust
    gate1 = (G1_X - 1.0 <= x <= G1_X + 1.0) and (G1_Y - 0.5 <= y <= G1_Y + 0.5)
    gate2 = (G2_X - 1.0 <= x <= G2_X + 1.0) and (G2_Y - 0.5 <= y <= G2_Y + 0.5)
    if gate1 or gate2:
        # Boost thrust by 30% but cap at MAX_THRUST
        thrust_mag = min(MAX_THRUST, thrust_mag * 1.3)

    # Adjust thrust based on position
    if x < 10.0:
        thrust_mag = min(100.0, thrust_mag)
    if 10.0 <= x <= 15.0:
        thrust_mag = min(MAX_THRUST, thrust_mag * 1.2)

    # Calculate waypoint to bypass gates and high-drag zones
    wx, wy = _waypoint(x, y)
    if x > 24.0:
        wy = 4.0
    if x < G1_X + 0.5 and y < 1.2:
        wy = max(wy, 1.3)
    if y < 1.4:
        wy = max(wy, 1.5)
    if G2_X - 1.0 <= x <= G2_X + 2.0 and y < 1.9:
        wy = max(wy, 2.2)
    if 20.5 <= x <= G2_X + 1.0 and y < 1.85:
        wx, wy = x + 0.3, 2.5

    dx = wx - x
    dy = wy - y
    dist = math.sqrt(dx * dx + dy * dy)

    if dist < 1e-6:
        sandbox.apply_thrust(0.0, 75.0)
        return

    ux = dx / dist
    uy = dy / dist
    fx = thrust_mag * ux
    fy = thrust_mag * uy

    # Avoid excessive force additions in high-risk areas
    if DRAIN_LO <= x <= DRAIN_HI or gate1 or gate2:
        # No additional forces in high-risk areas
        pass
    else:
        # Apply wind force in normal regions
        if WIND_LO <= x <= WIND_HI:
            wind_fy = WIND_AMP * math.sin(WIND_OMEGA * step_idx)
            fy -= wind_fy

    total = math.sqrt(fx * fx + fy * fy)
    cap = thrust_mag * 2.5
    if y < 1.4:
        cap = max(cap, 120.0)
    if 20.5 <= x <= G2_X + 2.0 and y < 1.9:
        cap = max(cap, 180.0)

    if total > cap:
        scale = cap / total
        fx *= scale
        fy *= scale

    sandbox.apply_thrust(fx, fy)
